// This file is generated by Vite build from src/main.ts
// Initial static version - replaced by Vite build
(function() {
  // Theme persistence
  const stored = localStorage.getItem('marksafe-theme');
  if (stored) document.body.className = stored;
  else if (window.matchMedia('(prefers-color-scheme: dark)').matches) document.body.className = 'dark';
  else document.body.className = 'light';
  
  // Theme toggle
  window.__toggleTheme = function() {
    const body = document.body;
    const next = body.className === 'dark' ? 'light' : 'dark';
    body.className = next;
    localStorage.setItem('marksafe-theme', next);
  };
  
  // Entry point
  console.log('MarkSafe Browse loaded');
})();
